// Real shared registry/writers and native editor filesystem round trips.
#include "modular_weapons.h"
#include "cartridge_damage.h"
#include "pxwe_project.h"
#include <algorithm>
#include <chrono>
#include <fstream>
#include <functional>
#include <iostream>
#include <locale>
#include <map>
#include <stdexcept>

namespace {
using Pack=std::map<std::string,std::string>;
int passed=0,failed=0;
void Check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void Test(const char* name,const std::function<void()>& action){try{action();++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cerr<<"FAIL "<<name<<": "<<e.what()<<'\n';}}
modular::Registry Load(const Pack& pack){modular::Registry registry;registry.Load([&](const std::string& path,std::string& data){const auto f=pack.find(path);if(f==pack.end())return false;data=f->second;return true;});return registry;}
void Valid(const modular::Registry& registry){Check(registry.Valid(),registry.Diagnostics().empty()?"Invalid registry":registry.Diagnostics().front().message.c_str());}
void Invalid(const Pack& pack){const auto registry=Load(pack);Check(!registry.Valid()&&!registry.Diagnostics().empty()&&registry.Weapons().empty()&&registry.Cartridges().empty(),"Invalid pack was not rejected atomically");}
void Replace(std::string& data,const std::string& before,const std::string& after){const auto p=data.find(before);Check(p!=std::string::npos,"Fixture replacement");data.replace(p,before.size(),after);}
modular::Cartridge Cartridge(int schema=3){modular::Cartridge c;c.id="fmj";c.chamber="9x19";c.projectileType="fmj";c.massGrams=8;c.diameterMm=9;c.dragCoefficient=.3f;c.referenceVelocityMps=360;c.schemaVersion=schema;c.damage=18;c.damageCoefficient=schema>=3?2:0;return c;}
modular::Weapon Weapon(){modular::Weapon w;w.schemaVersion=3;w.id="pistol";w.displayName="Pistol";w.ammoName=w.defaultCartridgeId="fmj";w.runtimeId=32;w.clipSize=15;w.defaultAmmo=30;w.maxCarry=120;w.slot=1;
    w.viewModel="models/v_9mmhandgun.mdl";w.playerModel="models/p_9mmhandgun.mdl";w.worldModel="models/w_9mmhandgun.mdl";w.compatible={{"fmj",360},{"jhp",300}};return w;}
const std::string weaponPath="scripts/weapons/pistol.weapon",cartridgePath="scripts/cartridges/fmj.cartridge";
Pack Basic(){auto c=Cartridge(2);c.id="jhp";return {{"scripts/cartridges/manifest.txt","fmj\njhp\n"},{"scripts/weapons/manifest.txt","pistol\n"},{cartridgePath,modular::SerializeCartridge(Cartridge())},{"scripts/cartridges/jhp.cartridge",modular::SerializeCartridge(c)},{weaponPath,modular::SerializeWeapon(Weapon())}};}
std::string Asset(const std::string& id,const std::string& role,const std::string& path,const std::string& when="default"){return "asset."+id+".role = "+role+"\nasset."+id+".path = "+path+"\nasset."+id+".when = "+when+"\n";}
Pack Extended(){auto pack=Basic();pack[cartridgePath]+="category = 9mm/FMJs\nsprite = sprites/9mm.spr\n";pack[weaponPath]+="category = pistols/compact\n"+Asset("normal","view_model","models/v_9mmhandgun.mdl")+Asset("automatic","view_model","models/v_9mmhandgun.mdl","mode:auto")+Asset("jhp_view","view_model","models/v_9mmhandgun.mdl","ammo:jhp")+Asset("fire1","fire_sound","weapons/pl_gun3.wav","random")+Asset("fire2","fire_sound","weapons/pl_gun3.wav","random")+Asset("icon","hud_sprite","sprites/weapon_9mmhandgun.txt")+Asset("kill","kill_sprite","sprites/9mm.spr")+"ammo.jhp.fire_sound = weapons/pl_gun3.wav\nammo.jhp.reload_sound = weapons/357_reload1.wav\nammo.jhp.sprite = sprites/9mm.spr\n";return pack;}
struct Temp {pxwe::fs::path path;Temp(){path=pxwe::fs::temp_directory_path()/("format-j10693-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));pxwe::fs::create_directory(path);}~Temp(){std::error_code e;pxwe::fs::remove_all(path,e);}};
void Put(const pxwe::fs::path& root,const Pack& pack){for(const auto& f:pack){const auto path=root/pxwe::fs::u8path(f.first);pxwe::fs::create_directories(path.parent_path());std::ofstream out(path);out<<f.second;Check(bool(out),"Fixture write");}}
Pack Disk(const pxwe::fs::path& root){Pack p;for(const auto& e:pxwe::fs::recursive_directory_iterator(root))if(e.is_regular_file()){std::ifstream in(e.path());p[pxwe::fs::relative(e.path(),root).generic_u8string()]=std::string(std::istreambuf_iterator<char>(in),{});}return p;}
}
int main(int argc,char** argv){
    Test("format3 coefficient category and ammo sprite load",[]{const auto r=Load(Extended());Valid(r);const auto* c=r.FindCartridge("fmj");Check(c->schemaVersion==3&&c->damageCoefficient==2&&c->category=="9mm/FMJs"&&c->sprite=="sprites/9mm.spr","Cartridge extension lost");});
    Test("conditional models sounds and sprites retain typed conditions",[]{const auto r=Load(Extended());Valid(r);const auto* w=r.FindWeapon("pistol");Check(w->schemaVersion==3&&w->category=="pistols/compact"&&w->assets.size()==7,"Weapon extensions lost");int def=0,random=0,mode=0,ammo=0;for(const auto& a:w->assets){def+=a.condition==modular::AssetCondition::Default;random+=a.condition==modular::AssetCondition::Random;mode+=a.condition==modular::AssetCondition::FireMode;ammo+=a.condition==modular::AssetCondition::Cartridge;}Check(def==3&&random==2&&mode==1&&ammo==1,"Condition classification");});
    Test("allowed-ammunition overrides retain distinct roles",[]{const auto r=Load(Extended());Valid(r);const auto& a=r.FindWeapon("pistol")->ammoOverrides;Check(a.size()==1&&a[0].cartridgeId=="jhp"&&a[0].fireSound=="weapons/pl_gun3.wav"&&a[0].reloadSound=="weapons/357_reload1.wav"&&a[0].sprite=="sprites/9mm.spr","Override fields lost");});
    Test("all supported ammunition override roles round trip",[]{auto p=Basic();for(const auto& key:{"view_model","player_model","world_model"})p[weaponPath]+="ammo.fmj."+std::string(key)+" = models/v_9mmhandgun.mdl\n";for(const auto& key:{"fire_sound","reload_sound"})p[weaponPath]+="ammo.fmj."+std::string(key)+" = weapons/pl_gun3.wav\n";for(const auto& key:{"sprite","hud_sprite","kill_sprite"})p[weaponPath]+="ammo.fmj."+std::string(key)+" = sprites/9mm.spr\n";auto r=Load(p);Valid(r);p[weaponPath]=modular::SerializeWeapon(*r.FindWeapon("pistol"));const auto again=Load(p);Valid(again);Check(r.Fingerprint()==again.Fingerprint(),"Override canonical digest");});
    Test("one default per role rejects a second default",[]{auto p=Basic();p[weaponPath]+=Asset("a","fire_sound","weapons/a.wav")+Asset("b","fire_sound","weapons/b.wav");Invalid(p);});
    Test("one default in separate roles is permitted",[]{auto p=Basic();p[weaponPath]+=Asset("a","fire_sound","weapons/a.wav")+Asset("b","reload_sound","weapons/b.wav");Valid(Load(p));});
    Test("omitted when means default and participates in uniqueness",[]{auto p=Basic();p[weaponPath]+="asset.a.role = fire_sound\nasset.a.path = weapons/a.wav\n"+Asset("b","fire_sound","weapons/b.wav");Invalid(p);});
    Test("duplicate variant IDs and repeated keys reject",[]{auto p=Basic();p[weaponPath]+=Asset("a","fire_sound","weapons/a.wav","random")+Asset("A","fire_sound","weapons/b.wav","random");Invalid(p);p=Basic();p[weaponPath]+=Asset("a","fire_sound","weapons/a.wav")+"asset.a.path = weapons/b.wav\n";Invalid(p);});
    Test("missing unknown and malformed variant fields reject",[]{for(const std::string& extra:std::vector<std::string>{"asset.a.role = fire_sound\n","asset.a.path = weapons/a.wav\n","asset.a.unknown = bad\n","asset.a = bad\n","asset..path = weapons/a.wav\n","asset.a.b.role = fire_sound\n"}){auto p=Basic();p[weaponPath]+=extra;Invalid(p);}});
    Test("unknown roles conditions and fire modes reject",[]{for(const auto& triple:std::vector<std::vector<std::string>>{{"bad","weapons/a.wav","default"},{"fire_sound","weapons/a.wav","sometimes"},{"fire_sound","weapons/a.wav","mode:fast"},{"fire_sound","weapons/a.wav","mode:"}}){auto p=Basic();p[weaponPath]+=Asset("a",triple[0],triple[1],triple[2]);Invalid(p);}});
    Test("ammunition conditions and overrides require allowed references",[]{for(const std::string& extra:std::vector<std::string>{Asset("a","view_model","models/v.mdl","ammo:missing"),"ammo.missing.fire_sound = weapons/a.wav\n","ammo.jhp.unknown = weapons/a.wav\n"}){auto p=Basic();p[weaponPath]+=extra;Invalid(p);}});
    Test("registered but disallowed ammunition cannot own an override",[]{auto p=Basic();Replace(p[weaponPath],"accept = jhp:300\n","");p[weaponPath]+="ammo.jhp.fire_sound = weapons/a.wav\n";Invalid(p);});
    Test("variant paths reject escape absolute and wrong resource types",[]{for(const std::string path:{"../a.wav","C:/a.wav","/a.wav","weapons/a.mdl","weapons/a b.wav"}){auto p=Basic();p[weaponPath]+=Asset("a","fire_sound",path);Invalid(p);}});
    Test("variant count is bounded",[]{auto p=Basic();for(int i=0;i<129;++i)p[weaponPath]+=Asset("v"+std::to_string(i),"fire_sound","weapons/a.wav","random");Invalid(p);});
    Test("nested categories preserve IDs and manifests",[]{auto p=Extended();const auto manifests=std::make_pair(p.at("scripts/weapons/manifest.txt"),p.at("scripts/cartridges/manifest.txt"));const auto r=Load(p);Valid(r);Check(r.FindWeapon("pistol")&&r.FindCartridge("fmj"),"Category changed identity");Check(manifests.first=="pistol\n"&&manifests.second=="fmj\njhp\n","Category changed manifests");});
    Test("malformed and over-deep categories reject",[]{for(const std::string& cat:std::vector<std::string>{"/rifles","rifles/","rifles//sg","rifles/../sg","rifles/with spaces",std::string(256,'a'),"a/a/a/a/a/a/a/a/a/a/a/a/a/a/a/a/a"}){auto p=Basic();p[weaponPath]+="category = "+cat+"\n";Invalid(p);p=Basic();p[cartridgePath]+="category = "+cat+"\n";Invalid(p);}});
    Test("format1 and format2 keep original damage behavior",[]{for(int v:{1,2}){auto p=Basic();p[cartridgePath]=modular::SerializeCartridge(Cartridge(v));const auto r=Load(p);Valid(r);Check(modular::MuzzleDamage(*r.FindCartridge("fmj"),100)==(v==1?20:18),"Legacy damage changed");Check(modular::SerializeCartridge(*r.FindCartridge("fmj")).find("damage_coefficient")==std::string::npos,"Silent cartridge conversion");}});
    Test("older formats reject new metadata rather than drop it",[]{for(const std::string& extra:std::vector<std::string>{"category = pistols\n",Asset("a","fire_sound","weapons/a.wav"),"ammo.fmj.fire_sound = weapons/a.wav\n"}){auto p=Basic();Replace(p[weaponPath],"version = 3","version = 2");p[weaponPath]+=extra;Invalid(p);}auto p=Basic();p[cartridgePath]=modular::SerializeCartridge(Cartridge(2))+"category = ammo\n";Invalid(p);});
    Test("coefficient rejects missing mixed nonfinite and nonpositive values",[]{for(const std::string value:{"nan","inf","-1","0","1000001"}){auto p=Basic();Replace(p[cartridgePath],"damage_coefficient = 2","damage_coefficient = "+value);Invalid(p);}auto p=Basic();p[cartridgePath]+="damage = 18\n";Invalid(p);p=Basic();Replace(p[cartridgePath],"damage_coefficient = 2\n","");Invalid(p);});
    Test("reference and compatible coefficient-derived damage are validated",[]{auto p=Basic();Replace(p[cartridgePath],"reference_velocity_mps = 360","reference_velocity_mps = 10000");Invalid(p);p=Basic();Replace(p[weaponPath],"accept = fmj:360","accept = fmj:10000");Invalid(p);});
    Test("shared formula specifies joules per circular mm2",[]{const auto c=Cartridge();const double expected=518.4/(3.141592653589793*81*.25)*2;Check(std::abs(modular::MuzzleDamage(c,360)-expected)<1e-8,"Units or area formula");});
    Test("canonical serialization retains every extended field",[]{auto p=Extended();const auto r=Load(p);Valid(r);for(const auto& c:r.Cartridges())p["scripts/cartridges/"+c.id+".cartridge"]=modular::SerializeCartridge(c);for(const auto& w:r.Weapons())p["scripts/weapons/"+w.id+".weapon"]=modular::SerializeWeapon(w);const auto again=Load(p);Valid(again);Check(r.Fingerprint()==again.Fingerprint()&&again.FindWeapon("pistol")->assets.size()==7,"Canonical extension loss");});
    Test("variant source and vector order have canonical digests",[]{auto p=Extended();auto r=Load(p);Valid(r);auto w=*r.FindWeapon("pistol");const auto before=modular::SerializeWeapon(w);std::reverse(w.assets.begin(),w.assets.end());std::reverse(w.ammoOverrides.begin(),w.ammoOverrides.end());Check(before==modular::SerializeWeapon(w),"Vector order changed canonical bytes");p[weaponPath]=before;const auto another=Load(p);Valid(another);Check(r.Fingerprint()==another.Fingerprint(),"Source order changed canonical digest");});
    Test("every new semantic field affects the shared digest",[]{const auto p=Extended();const auto before=Load(p).Fingerprint();for(const auto& change:std::vector<std::vector<std::string>>{{cartridgePath,"damage_coefficient = 2","damage_coefficient = 3"},{cartridgePath,"9mm/FMJs","9mm/other"},{cartridgePath,"sprites/9mm.spr","sprites/ammo.spr"},{weaponPath,"pistols/compact","pistols/full"},{weaponPath,"weapons/357_reload1.wav","weapons/reload.wav"},{weaponPath,"mode:auto","mode:semi"},{weaponPath,"asset.normal.path = models/v_9mmhandgun.mdl","asset.normal.path = models/v_other.mdl"}}){auto altered=p;Replace(altered[change[0]],change[1],change[2]);const auto r=Load(altered);Valid(r);Check(r.Fingerprint()!=before,"Missing field in fingerprint");}});
    Test("classic-locale canonical numbers preserve their decimal grammar",[]{struct Punct:std::numpunct<char>{char do_decimal_point()const override{return ',';}};const auto before=modular::SerializeCartridge(Cartridge());const auto old=std::locale();std::locale::global(std::locale(old,new Punct));const auto after=modular::SerializeCartridge(Cartridge());std::locale::global(old);Check(before==after,"Locale changed canonical bytes");});
    Test("native editor saves reloads and undoes extended metadata",[]{Temp t;Put(t.path,Extended());pxwe::Project project;project.Load(t.path);const auto hash=project.Validate().registry.Fingerprint();Check(project.Validate().Ok(),"Editor cannot load format3");project.SetField(pxwe::Kind::Weapon,"pistol","category","pistols/service");Check(project.Undo()&&project.Validate().registry.Fingerprint()==hash,"Undo lost variants");Check(project.Redo(),"Redo failed");project.Save();pxwe::Project reload;reload.Load(t.path);Check(reload.Validate().Ok()&&reload.Validate().registry.FindWeapon("pistol")->assets.size()==7,"Save/reload lost variants");});
    Test("invalid extended editor save writes no files",[]{Temp t;Put(t.path,Extended());pxwe::Project project;project.Load(t.path);const auto before=Disk(t.path);project.SetField(pxwe::Kind::Weapon,"pistol","ammo.missing.fire_sound","weapons/a.wav");bool rejected=false;try{project.Save();}catch(const std::exception&){rejected=true;}Check(rejected&&Disk(t.path)==before,"Invalid format export touched files");});
    if(argc==2)Test("old shipped fingerprint and new sample admission",[&]{pxwe::Project old;old.Load(pxwe::fs::path(argv[1])/"documentation/examples/modular-ballistics");Check(old.Validate().Ok()&&old.Validate().registry.Fingerprint()==1605249880u,"Old shipped digest changed");pxwe::Project sample;sample.Load(pxwe::fs::path(argv[1])/"documentation/examples/modular-format3");Check(sample.Validate().Ok(),"Format3 sample invalid");});
    std::cout<<passed<<" passed, "<<failed<<" failed\n";return failed?1:0;
}
